import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not isinstance(script_path, str):
        raise TypeError("script_path must be a string")
    if not os.path.exists(script_path):
        raise OSError("script_path does not exist")
    proc = subprocess.Popen(['bash', script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    try:
        p = psutil.Process(proc.pid)
    except psutil.NoSuchProcess:
        return {'CPU Usage': 0.0, 'Memory Usage': 0}
    cpu_usage = 0.0
    mem_usage = 0
    start_time = time.time()
    while True:
        try:
            cpu_percent = p.cpu_percent(interval=0.0)
            mem_info = p.memory_info()
            cpu_usage += cpu_percent
            mem_usage += mem_info.rss
        except (psutil.NoSuchProcess, psutil.ZombieProcess):
            break
        if time.time() - start_time > timeout:
            proc.terminate()
            break
        time.sleep(0.1)
        if not p.is_running():
            break
    if p.is_running():
        proc.terminate()
    return {'CPU Usage': cpu_usage, 'Memory Usage': mem_usage}
